import unicodedata


def _cwidth(ch):
    if unicodedata.combining(ch) > 0 or unicodedata.category(ch) in ("Mn", "Me", "Cf"):
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
        return 2
    return 1


def _width(s):
    return sum(_cwidth(ch) for ch in s)


def truncate(text, width, ellipsis="…"):
    if width < 0:
        raise ValueError("width must not be negative")
    text = unicodedata.normalize("NFC", text)
    if _width(text) <= width:
        return text
    avail = width - _width(ellipsis)
    if avail < 0:
        raise ValueError("ellipsis is wider than width")

    # Split into clusters: a character plus the zero-width characters after it.
    clusters = []
    for ch in text:
        if _cwidth(ch) == 0 and clusters:
            clusters[-1] += ch
        else:
            clusters.append(ch)

    prefix = ""
    used = 0
    for cluster in clusters:
        w = _width(cluster)
        if used + w > avail:
            break
        prefix += cluster
        used += w
    return prefix.rstrip() + ellipsis
